"""Icônes vectorielles pour les étiquettes.

Pour ajouter une icône : écrire une fonction dessinant dans un carré 0..1
(origine en bas à gauche) puis l'enregistrer dans ICONS.
"""
import math

# Dessinées dans un carré 0..1, trait noir, y vers le haut.

class Pen:
    def __init__(self):
        self.ops = []

    def line(self, *pts):
        o = self.ops
        o.append("%.3f %.3f m" % pts[0])
        for p in pts[1:]:
            o.append("%.3f %.3f l" % p)
        o.append("S")

    def poly(self, *pts):
        self.line(*pts)
        self.ops[-1] = "h S"

    def rect(self, x, y, w, h, fill=False):
        self.ops.append("%.3f %.3f %.3f %.3f re %s" % (x, y, w, h, "f" if fill else "S"))

    def circle(self, cx, cy, r, fill=False):
        k = 0.5523 * r
        self.ops.append(
            "%.3f %.3f m %.3f %.3f %.3f %.3f %.3f %.3f c %.3f %.3f %.3f %.3f %.3f %.3f c "
            "%.3f %.3f %.3f %.3f %.3f %.3f c %.3f %.3f %.3f %.3f %.3f %.3f c %s" % (
                cx + r, cy, cx + r, cy + k, cx + k, cy + r, cx, cy + r,
                cx - k, cy + r, cx - r, cy + k, cx - r, cy,
                cx - r, cy - k, cx - k, cy - r, cx, cy - r,
                cx + k, cy - r, cx + r, cy - k, cx + r, cy, "f" if fill else "S"))

    def arc_line(self, cx, cy, r, a0, a1, n=24):
        pts = [(cx + r * math.cos(math.radians(a0 + (a1 - a0) * i / n)),
                cy + r * math.sin(math.radians(a0 + (a1 - a0) * i / n))) for i in range(n + 1)]
        self.line(*pts)


def _lampe(p):
    p.circle(.5, .62, .27)
    p.line((.38, .38), (.38, .22)); p.line((.62, .38), (.62, .22))
    p.line((.38, .22), (.62, .22))
    p.line((.4, .12), (.6, .12))
    p.line((.42, .5), (.5, .62), (.58, .5))


def _four(p):
    p.rect(.08, .12, .84, .76)
    p.rect(.16, .12, .68, .46)
    p.line((.08, .72), (.92, .72))
    for x in (.25, .45, .65):
        p.circle(x, .8, .03, True)
    p.line((.3, .4), (.7, .4))


def _lave_linge(p):
    p.rect(.12, .06, .76, .88)
    p.line((.12, .78), (.88, .78))
    p.circle(.5, .42, .24); p.circle(.5, .42, .13)
    p.circle(.24, .86, .03, True); p.circle(.34, .86, .03, True)


def _lave_vaisselle(p):
    p.rect(.12, .06, .76, .88)
    p.line((.12, .78), (.88, .78))
    p.line((.25, .15), (.25, .55)); p.line((.4, .15), (.4, .55))
    p.line((.55, .15), (.55, .55)); p.line((.7, .15), (.7, .55))
    p.line((.2, .15), (.8, .15))
    p.circle(.24, .86, .03, True)


def _seche_linge(p):
    p.rect(.12, .06, .76, .88)
    p.line((.12, .78), (.88, .78))
    p.circle(.5, .42, .24)
    p.arc_line(.5, .42, .13, 20, 200)
    p.line((.4, .3), (.5, .38), (.6, .3))


def _chauffage(p):
    p.rect(.08, .2, .84, .6)
    for x in (.2, .35, .5, .65, .8):
        p.line((x, .26), (x, .74))
    p.line((.2, .2), (.2, .1)); p.line((.8, .2), (.8, .1))


def _frigo(p):
    p.rect(.22, .05, .56, .9)
    p.line((.22, .62), (.78, .62))
    p.line((.3, .72), (.3, .86)); p.line((.3, .12), (.3, .5))


def _chauffe_eau(p):
    p.rect(.25, .06, .5, .88)
    p.circle(.5, .5, .14)
    p.line((.42, .5), (.58, .5))
    p.line((.35, .06), (.35, 0.0)); p.line((.65, .06), (.65, 0.0))


def _vmc(p):
    p.circle(.5, .5, .42)
    for a in (90, 210, 330):
        r = math.radians(a)
        cx, cy = .5 + .2 * math.cos(r), .5 + .2 * math.sin(r)
        p.circle(cx, cy, .13)
    p.circle(.5, .5, .04, True)


def _prise_ext(p):
    p.rect(.1, .1, .8, .6)
    p.circle(.37, .4, .05, True); p.circle(.63, .4, .05, True)
    p.arc_line(.5, .7, .3, 0, 180)


def _multimedia(p):
    p.rect(.06, .28, .88, .6)
    p.rect(.12, .34, .76, .48)
    p.line((.35, .12), (.65, .12)); p.line((.5, .12), (.5, .28))


def _sonnette(p):
    p.arc_line(.5, .45, .3, 0, 180)
    p.line((.2, .45), (.2, .25)); p.line((.8, .45), (.8, .25))
    p.line((.12, .25), (.88, .25))
    p.circle(.5, .13, .05, True)
    p.line((.5, .75), (.5, .85))


def _differentiel(p):
    p.rect(.15, .15, .7, .7)
    p.line((.15, .6), (.85, .6))
    p.line((.4, .6), (.4, .85)); p.line((.4, .38), (.6, .38))
    p.circle(.5, .38, .0)
    p.line((.35, .38), (.65, .38))


def _general(p):
    p.line((.55, .95), (.25, .5), (.5, .5), (.4, .05), (.75, .6), (.5, .6), (.55, .95))


def _trace(ops):
    def dessiner(p):
        p.ops.append(ops)
    return dessiner


